import{_ as a,o as n,c as i,a5 as t}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/neo4j-all-nodes/plan.md","filePath":"feature/neo4j-all-nodes/plan.md"}'),o={name:"feature/neo4j-all-nodes/plan.md"};function r(s,e,l,d,p,c){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h1><ol><li>New AI overview selection/page model, parameterized keyset node query and bounded induced-edge query. Preserve any label in all-scope node mapping; public mapping unchanged. Reuse read-only/timeouts/real-driver guard.</li><li>Add scope public/all to expand, apply unrestricted node/relationship read only for explicit all; preserve caps. New overview API internal key.</li><li>Business admin-only overview proxy with bounded validation; explicit scoped expand overload preserves existing Java callers. No access-rule changes to public endpoints.</li><li>Web overview response schema/API method and All nodes mode with search/page-size/keyset previous stack/refetch; reuse workspace with scope=all, no default-hidden posts, disconnected nodes visible. Error/empty have no invented graph.</li><li>Existing test files cover keyset continuation, unknown/disconnected/brand nodes, edge caps/projection, scoped expand, auth/validation; run AI, Business tests and Web CI. Use isolated local Neo4j fixture for actual queries if available; never shared DB writes.</li></ol><h2 id="large-graph-plan" tabindex="-1">Large graph plan <a class="header-anchor" href="#large-graph-plan" aria-label="Permalink to &quot;Large graph plan&quot;">​</a></h2><ol><li>Add read-only keyset edge pages with identical all-node search predicate at both endpoints; admin proxy/auth and request limits remain bounded.</li><li>Separate bounded wire graph schema from uncapped in-memory scene merging. Progressive loader scans node batches then relationship batches with AbortController, operation identity and resumable cursors; completion requires both streams.</li><li>Build linear-time component layout plus stable incremental placement with spatial occupancy; explicit rearrange re-groups after links load. No global all-pairs force algorithm in overview.</li><li>Canvas overview renders the accumulated graph with viewport culling, level-of-detail/collision-aware labels, focus, pan/zoom/full-screen and accessible paginated node selector. Reuse workspace inspector, safe projection and real scoped expansion; public trend SVG unchanged.</li><li>Verify &gt;200 nodes and cross-batch relationships on isolated Neo4j, loader abort/failure/resume and layout separation/stability, frontend CI/Business/AI tests and local-only visual QA.</li></ol><h2 id="overview-interaction-parity-plan" tabindex="-1">Overview interaction parity plan <a class="header-anchor" href="#overview-interaction-parity-plan" aria-label="Permalink to &quot;Overview interaction parity plan&quot;">​</a></h2><p>Extend OverviewGraphCanvas pointer hit testing to distinguish node drag from background pan; capture pointer identity, retain world coordinates and manual positions. Add release/move controls and double-click expansion guard. Wire workspace highlight/edge labels and hidden types into Canvas; legend uses unfiltered categories so hidden types can be restored. Draw highlights/labels/manual-position markers with bounded screen detail. Update vi/en admin keys. No API/schema changes.</p><h2 id="rank-one-scan-plan" tabindex="-1">Rank-one scan plan <a class="header-anchor" href="#rank-one-scan-plan" aria-label="Permalink to &quot;Rank-one scan plan&quot;">​</a></h2><p>AI adds protected read-only GET overview/root and POST overview/neighbors. Neighbors accepts at most 50 frontier elementIds and 200 relationship rows, paginates by (center elementId, relationship elementId), returns safe projected endpoint nodes and edges. No fanout LIMIT loss; cycle-safe BFS visited sets in Web. Business validates bounded payload and requires admin before forwarding. Web HopGraphScan uses rank root -&gt; paged frontier chunks per depth -&gt; next unseen component from keyset pages. GraphScanController consumes a common scan-driver interface; existing GraphScan/public SVG kept. Auto-load all on mount, pause/resume existing buttons. Keep first root as graph rootId; initialize all-mode selection for seeded graph, Canvas starts centered on singleton root. Update vi/en admin phase/progress keys.</p><h2 id="post-visibility-right-pan-plan" tabindex="-1">Post visibility/right pan plan <a class="header-anchor" href="#post-visibility-right-pan-plan" aria-label="Permalink to &quot;Post visibility/right pan plan&quot;">​</a></h2><p>Reuse workspace hiddenLabels/onToggleLabel from OverviewGraphCanvas; add shared Switch with unique labelled id. Pointer drag state tracks canPan/selectOnRelease, right-button starts pan with no node target, left background drags cannot pan and right clicks never change focus. Keep capture/cancel handling, node drag, wheel and keyboard. Update admin vi/en hidePostNodes and overviewCanvasHint. No backend/data changes.</p><h2 id="relationship-context-plan" tabindex="-1">Relationship context plan <a class="header-anchor" href="#relationship-context-plan" aria-label="Permalink to &quot;Relationship context plan&quot;">​</a></h2><p>Remove selection-based edge omission from Canvas rendering and hit testing. Use existing Trend visual accent for related edges, stronger opacity/width and consistent arrow color; keep unrelated edges visible. Simplify hitOverviewEdge arguments after removing selection filter. Update vi/en focusLinks label. No API/data changes.</p>',12)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
